style.css:
@-moz-document domain("bloxflip.com") {
/* ========================= */
/* ? CLEAN BASE (same good theme) */
/* ========================= */

body {
    background-color: #0b0f0c !important;
    color: #d8ffe8 !important;
}

nav, header {
    background-color: #0d1410 !important;
    border-bottom: 1px solid rgba(0, 255, 140, 0.15) !important;
}

[class*="container"],
[class*="wrapper"],
[class*="content"],
[class*="panel"],
[class*="card"] {
    background-color: #101713 !important;
    border: 1px solid rgba(0, 255, 140, 0.08) !important;
    border-radius: 10px !important;
}

button {
    background: linear-gradient(135deg, #00ff88, #00c96b) !important;
    color: #022d1a !important;
    border-radius: 8px !important;
}

/* ========================= */
/* ? MULTI-DIRECTION PARTICLES */
/* ========================= */

/* Layer 1 - diagonal down right */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 9997;

    background-image:
        radial-gradient(circle, rgba(0,255,140,0.9) 2px, transparent 2px);

    background-size: 90px 90px;
    animation: move1 6s linear infinite;
}

/* Layer 2 - diagonal down left */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 9998;

    background-image:
        radial-gradient(circle, rgba(0,255,140,0.6) 1.5px, transparent 2px);

    background-size: 70px 70px;
    animation: move2 9s linear infinite;
}

/* Extra particle layer using html element */
html::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 9999;

    background-image:
        radial-gradient(circle, rgba(0,255,140,0.4) 1px, transparent 2px);

    background-size: 120px 120px;
    animation: move3 12s linear infinite;
}

/* ========================= */
/* ?️ DIFFERENT DIRECTIONS */
/* ========================= */

@keyframes move1 {
    from { transform: translate(0, 0); }
    to   { transform: translate(200px, 400px); }
}

@keyframes move2 {
    from { transform: translate(0, 0); }
    to   { transform: translate(-250px, 500px); }
}

@keyframes move3 {
    from { transform: translate(0, 0); }
    to   { transform: translate(150px, -300px); }
}
}
